urlset:
{%- for sitemap_entry in entries %}
{%- if not sitemap_entry.extra.noindex %}

    {{ sitemap_entry.permalink | escape_xml | safe }}
    {%- if sitemap_entry.updated %}
    {{ sitemap_entry.updated }}
    {%- elif latest and (sitemap_entry.permalink == config.base_url ~ "/" or sitemap_entry.permalink == blog.permalink) %}
    {{ latest }}
    {%- endif %}

{%- endif %}
{%- endfor %}
